// استخراج البيانات الأساسية فقط من تليجرام
const input = $input.first().json;

const message = input.message || {};
const chat = message.chat || {};
const from = message.from || {};

const customer_message = message.text || '';
const telegram_id = chat.id || from.id || '';
const chat_id = chat.id || '';
const customer_name = [from.first_name, from.last_name].filter(Boolean).join(' ') || 'عميل تليجرام';

// الوقت والتاريخ بتوقيت الأردن المحلي
const date_time = new Date().toLocaleString('ar-JO', { timeZone: 'Asia/Amman' });

return {
  json: {
    telegram_id: String(telegram_id),
    chat_id: String(chat_id),
    customer_name: customer_name,
    customer_message: customer_message,
    date_time: date_time
  }
};
